import{af as i,z as e,J as a,ab as o}from"./chunks/framework.DTM_IFrD.js";const p=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"apps/cloud/device-settings/notifications.md","filePath":"apps/cloud/device-settings/notifications.md"}'),n={name:"apps/cloud/device-settings/notifications.md"};function r(s,t,c,l,d,g){return e(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793271754000"},[...t[0]||(t[0]=[o('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>The notifications section of device settings allows you to manage events trigger notifications for a device.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/XLqc2we.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="delivery" tabindex="-1">Delivery <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;Delivery&quot;">​</a></h2><p>To update how you are notified, you will need to go to the Account tab.</p><p>There you can enable mobile push notifications, email alerts and API push notifications.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/3Nj7E61.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="status-notifications" tabindex="-1">Status Notifications <a class="header-anchor" href="#status-notifications" aria-label="Permalink to &quot;Status Notifications&quot;">​</a></h2><p>Low Battery alert will trigger when the battery level reaches 30%.</p><p>You can also trigger this when the battery level is 15%.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/9AZ3jrk.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="motion-notifications" tabindex="-1">Motion Notifications <a class="header-anchor" href="#motion-notifications" aria-label="Permalink to &quot;Motion Notifications&quot;">​</a></h2><ul><li><strong>All new locations when moving</strong> alert will trigger when new location updates are sent by the tracker, but only when there is motion.</li><li><strong>Device starts moving</strong> alert will trigger when the device when a stationary tracker starts moving.</li><li><strong>Device stops moving</strong> alert will trigger when a moving device becomes stationary.</li><li><strong>A fall is detected</strong> alert will trigger when the tracker has been dropped.</li><li><strong>Tampering is detected</strong> alert will trigger when possible device tampering is detected.</li></ul><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/PZm66bJ.png" alt="" tabindex="0"><figcaption></figcaption></figure><h2 id="zone-notifications" tabindex="-1">Zone Notifications <a class="header-anchor" href="#zone-notifications" aria-label="Permalink to &quot;Zone Notifications&quot;">​</a></h2><p>To set various geofencing alerts, you will need to go to the Geofence Editor Section in the Account tab</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/JO9EzeN.png" alt="" tabindex="0"><figcaption></figcaption></figure><div class="info custom-block"><p class="custom-block-title">ℹ️ Information</p><p>A Geofence (sometimes called a GPS safe-zone) is a virtual border around a specific area. You can set up alerts for when your device enters/leaves this specific area.</p></div>',18)])])}const u=i(n,[["render",r]]);export{p as __pageData,u as default};
